using System;
using System.Threading.Tasks; using Microsoft.AspNetCore.Builder; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; using Microsoft.eShopWeb.ApplicationCore.Services; using MinimalApi.Endpoint;  namespace Microsoft.eShopWeb.PublicApi.SubscriptionEndpoints;  public class ListMySubscriptionsEndpoint : IEndpoint<IResult, ListMySubscriptionsRequest> {     private readonly IMaxioClient _maxio;     private readonly ISubscriptionMappingService _map;     private readonly IHttpContextAccessor _httpAccessor;      public ListMySubscriptionsEndpoint(IMaxioClient maxio, ISubscriptionMappingService map, IHttpContextAccessor httpAccessor)     {         _maxio = maxio;         _map = map;         _httpAccessor = httpAccessor;     }      public void AddRoute(IEndpointRouteBuilder app)     {         app.MapGet("api/my-subscriptions",             async () => await HandleAsync(new ListMySubscriptionsRequest()))             .Produces<ListMySubscriptionsResponse>()             .WithTags("SubscriptionEndpoints")             .RequireAuthorization();     }      public async Task<IResult> HandleAsync(ListMySubscriptionsRequest request)     {         var response = new ListMySubscriptionsResponse(request.CorrelationId());         var user = _httpAccessor.HttpContext?.User;         var userId = user?.Identity?.Name ?? user?.FindFirst("sub")?.Value ?? "unknown";         var reference = _map.GetCustomerReference(userId);          try         {             if (!string.IsNullOrEmpty(reference))             {                 var subs = await _maxio.ListSubscriptionsAsync(reference);                 foreach (var s in subs)                 {                     response.Subscriptions.Add(new MySubscriptionDto                     {                         Id = s.Id,                         PlanHandle = s.ProductHandle,                         PlanName = s.ProductName,                         State = s.State,                         PriceMonthly = s.PriceInCents,                         NextBillingDate = s.NextBillingDate                     });                 }             }         }                 catch (Exception ex)         {             return Results.BadRequest(new { error = "Failed to load subscriptions: " + ex.Message });         }         return Results.Ok(response);     } }
